text:
{"page_han_chars": 231,
 "errors": [
  {"type": "omitted", "transcription": "", "page": "力乎一息之逸充其至可以", "context": "況窮日之"},
  {"type": "omitted", "transcription": "", "page": "非民所訓非天", "context": "凡為耽樂皆"},
  {"type": "misread", "transcription": "譌", "page": "譸", "context": "民無或胥"},
  {"type": "misread", "transcription": "譌", "page": "譸", "context": "匡救也"}
 ],
 "error_chars": 19,
 "verdict": "material",
 "notes": "The transcription leaves out two spans of the interlinear note on 耽樂 (17 characters in total), and it twice writes 譌 where the page has 譸 in 譸張; everything else matches the page."}

{"page_han_chars": 330,
 "errors": [
  {"type": "omitted", "transcription": "", "page": "晉有謝安桓沖而陛下伐之臣竊惑焉堅", "context": "寵於堅諫曰"},
  {"type": "misread", "transcription": "着", "page": "肴", "context": "謂悰曰"},
  {"type": "misread", "transcription": "如此", "page": "比", "context": "其威譽德業"},
  {"type": "misread", "transcription": "管", "page": "卹", "context": "辦事為效不"}
 ],
 "error_chars": 20,
 "verdict": "material",
 "notes": "A full 16-character column (晉有謝安…惑焉堅) is missing after 諫曰; the transcription also adds a ｜ after 矣 that is not on the page and writes 蔬 where the page seems to show the 疏 form, neither counted."}

{"page_han_chars": 160,
 "errors": [
  {"type": "misread", "transcription": "銃", "page": "銳", "context": "斥鴳鷽鳩之"},
  {"type": "invented", "transcription": "一", "page": "", "context": "而不知其中"},
  {"type": "omitted", "transcription": "", "page": "夫", "context": "墮也倏忽矣"}
 ],
 "error_chars": 3,
 "verdict": "minor",
 "notes": "The image is clear and the page has 8 columns of 20 characters; I called this minor although 3 of 160 characters is about 1.9%, which sits on the line between minor and material."}

{"page_han_chars": 232,
 "errors": [
  {"type": "order", "transcription": "釋史墨知夢非日食之應故日食", "page": "史墨知夢非日食之應故釋日食", "context": "終亦弗克"},
  {"type": "omitted", "transcription": "", "page": "去", "context": "十月十九日"},
  {"type": "misread", "transcription": "婦", "page": "妻", "context": "金為火妃夫"}
 ],
 "error_chars": 3,
 "verdict": "minor",
 "notes": "The transcription puts 釋 at the start of a double-column note when it belongs after 故, drops 去 after 十九日, and gives 夫婦 where the page has 夫妻; everything else matches."}

{"page_han_chars": 262,
 "errors": [
  {"type": "misread", "transcription": "瞬", "page": "變", "context": "輅曰含氣須"},
  {"type": "misread", "transcription": "巢", "page": "窠", "context": "所住戶有燕"},
  {"type": "invented", "transcription": "孫", "page": "", "context": "喻趙飛燕害皇"}
 ],
 "error_chars": 3,
 "verdict": "minor",
 "notes": "The page ends at 害皇, so 孫 belongs to the next leaf; the character in 不恐復雙飛 is unclear and was not counted as an error."}

{"page_han_chars": 370,
 "errors": [
  {"type": "misread", "transcription": "羝", "page": "疆", "context": "陸績作場"},
  {"type": "misread", "transcription": "漢食貨志同", "page": "象數合", "context": "易乃古文疆場字與"},
  {"type": "omitted", "transcription": "", "page": "觸物大壯衆陽並", "context": "語喪羊于易羣行而"}
 ],
 "error_chars": 13,
 "verdict": "material",
 "notes": "I couldn't read the small interlinear marks at '廸和〇' clearly enough to judge them; the 〇 before 集解 isn't clearly visible either, so neither is counted as an error."}

{"page_han_chars": 400,
 "errors": [
  {"type": "omitted", "transcription": "", "page": "——錢起詩勉事壺公術仙期待", "context": "天人執節乘——"},
  {"type": "omitted", "transcription": "", "page": "作——", "context": "結——爲——"},
  {"type": "omitted", "transcription": "", "page": "燈", "context": "何照謝朓"}
 ],
 "error_chars": 13,
 "verdict": "material",
 "notes": "The transcription leaves out a whole quotation (錢起詩…期待) at the end of the 騎龍 entry, plus 作 and 燈; the rest matches the page."}
